import{_ as e}from"./chunks/mob2-report-form.a813b616.js";import{_ as t,o as a,c as n,Q as s}from"./chunks/framework.b67c47e6.js";const b=JSON.parse('{"title":"MOB v1 Machine File","description":"","frontmatter":{},"headers":[],"relativePath":"guide/machine_files/formats/panel_mob1/index.md","filePath":"guide/machine_files/formats/panel_mob1/index.md","lastUpdated":1790618281000}'),o={name:"guide/machine_files/formats/panel_mob1/index.md"},i=s('<h1 id="mob-v1-machine-file" tabindex="-1">MOB v1 Machine File <a class="header-anchor" href="#mob-v1-machine-file" aria-label="Permalink to &quot;MOB v1 Machine File&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">Beta — under review</p><p>This page is new and is still being checked against the machines. It may be incomplete or contain mistakes, so do not rely on it alone for production settings. If something here does not match what you see, tell us.</p></div><p>The MOB v1 file is the first generation of the H&amp;M panel file, read by the <strong>Mobi One V1</strong> and the <strong>Frame Station V1</strong>. It works like the <a href="/guide/machine_files/formats/panel_mob2/">MOB v2 file</a>: one file per panel design, with the layers of every machine station of the line. This page lists what is different.</p><p><img src="'+e+`" alt="The report form for a MOB machine file"></p><p>Create it in <strong>Production files</strong> with <strong>MOB v1 Machine File</strong> as the report type, pick the production line, and set the job options of each station in its <strong>Station Job Options</strong> block.</p><nav class="table-of-contents"><ul><li><a href="#how-it-is-made">How it is made</a></li><li><a href="#what-is-in-the-file">What is in the file</a></li><li><a href="#job-options">Job options</a></li><li><a href="#output">Output</a></li><li><a href="#mob-v1-vs-mob-v2">MOB v1 vs. MOB v2</a></li></ul></nav><h2 id="how-it-is-made" tabindex="-1">How it is made <a class="header-anchor" href="#how-it-is-made" aria-label="Permalink to &quot;How it is made&quot;">​</a></h2><p>Zones, stations and the machine configuration file work as for MOB v2: see <a href="/guide/machine_files/formats/panel_mob2/#how-a-file-is-made">How a file is made</a>. The configuration file of a V1 machine is a text file of <code>key=value</code> lines, uploaded in the <strong>Machine file</strong> tab of the setup.</p><h2 id="what-is-in-the-file" tabindex="-1">What is in the file <a class="header-anchor" href="#what-is-in-the-file" aria-label="Permalink to &quot;What is in the file&quot;">​</a></h2><p>The same header and layer structure as MOB v2:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#e1e4e8;">VERSION       3.00;</span></span>
<span class="line"><span style="color:#e1e4e8;">TXT # MOB  Conversion by Produuz.it;</span></span>
<span class="line"><span style="color:#e1e4e8;">TXT # Design name: W-12;</span></span>
<span class="line"><span style="color:#e1e4e8;">REIHE     inside;</span></span>
<span class="line"><span style="color:#e1e4e8;">ELN      W-12;</span></span>
<span class="line"><span style="color:#e1e4e8;">ELM   4078,  2630,    69,     1,     0,     0;</span></span>
<span class="line"><span style="color:#e1e4e8;">Layer,     -1,   FRAMING,     1,     0,     0,  4078,  2630;</span></span>
<span class="line"><span style="color:#e1e4e8;">BR   1351,    44,    44,     0,     0,        01,H214 VUREN-C 44.0x44.0,     0,     0;</span></span>
<span class="line"><span style="color:#e1e4e8;">...</span></span>
<span class="line"><span style="color:#e1e4e8;">End Layer,     -1;</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292e;">VERSION       3.00;</span></span>
<span class="line"><span style="color:#24292e;">TXT # MOB  Conversion by Produuz.it;</span></span>
<span class="line"><span style="color:#24292e;">TXT # Design name: W-12;</span></span>
<span class="line"><span style="color:#24292e;">REIHE     inside;</span></span>
<span class="line"><span style="color:#24292e;">ELN      W-12;</span></span>
<span class="line"><span style="color:#24292e;">ELM   4078,  2630,    69,     1,     0,     0;</span></span>
<span class="line"><span style="color:#24292e;">Layer,     -1,   FRAMING,     1,     0,     0,  4078,  2630;</span></span>
<span class="line"><span style="color:#24292e;">BR   1351,    44,    44,     0,     0,        01,H214 VUREN-C 44.0x44.0,     0,     0;</span></span>
<span class="line"><span style="color:#24292e;">...</span></span>
<span class="line"><span style="color:#24292e;">End Layer,     -1;</span></span></code></pre></div><p>The differences:</p><ul><li><strong>Layer numbers.</strong> The frame is layer -1 or 1, and a plate zone is written one layer further out: zone -1 is layer -2, zone 1 is layer 2.</li><li><strong>Tool codes are shorter.</strong> Milling, sawing, drilling and gluing are written with the last digit of the tool: 8, 3, 2 and 9. A milling code of 2228 in MOB v2 is 228 in MOB v1.</li><li><strong>Ellipses</strong> are written as polygon paths.</li><li><strong>Gluing</strong> is written for frame glue lines only.</li></ul><p>The frame map (<code>BR</code>, <code>TR</code>, <code>HC</code>, <code>VC</code>, <code>AC4</code>), frame nailing (<code>NRY</code>), plates (<code>OS</code>), plate nailing (<code>NRZ</code>), milling and sawing paths (<code>PSG</code>, <code>PP</code>) and holes (<code>MP</code>) are the same commands as in MOB v2. See <a href="/guide/machine_files/formats/panel_mob2/#commands">Commands</a>.</p><h2 id="job-options" tabindex="-1">Job options <a class="header-anchor" href="#job-options" aria-label="Permalink to &quot;Job options&quot;">​</a></h2><p>The report form shows the same options as for MOB v2, with these differences:</p><table><thead><tr><th>Option</th><th>In MOB v1</th></tr></thead><tbody><tr><td><strong>Plates Nailer Tool ID</strong></td><td>4, 5 or 6, or <em>Single nailing from model</em>. There is no twin nailing.</td></tr><tr><td><strong>Screwdriver Tool ID</strong></td><td>0.</td></tr><tr><td><strong>Minimum panel height for twin nailing</strong></td><td>Not offered.</td></tr><tr><td><strong>Battens Tool ID</strong></td><td>4, 5 or 6.</td></tr><tr><td><strong>Milling, Sawing, Drilling, Gluing tool id</strong></td><td>One tool each, shown by its last digit: 8, 3, 2 and 9.</td></tr></tbody></table><p>All the other options — starting side, shift mode, trimming, custom matrix, mill and saw directions — behave as described in <a href="/guide/machine_files/formats/panel_mob2/#job-options">Job options</a>.</p><p>The spacing of plate nail lines comes from the model. The <strong>Default value for CTC in plates nailing</strong> of the machine setup is used for the lines that have none.</p><h2 id="output" tabindex="-1">Output <a class="header-anchor" href="#output" aria-label="Permalink to &quot;Output&quot;">​</a></h2><p>A ZIP with one <code>.mob</code> file per design, named after the design and its revision, in a folder per phase and batch, with an <code>.orientation.txt</code> next to each file and the operation drawings in <code>pics/</code>. See <a href="/guide/machine_files/formats/panel_mob2/#output">Output</a>.</p><h2 id="mob-v1-vs-mob-v2" tabindex="-1">MOB v1 vs. MOB v2 <a class="header-anchor" href="#mob-v1-vs-mob-v2" aria-label="Permalink to &quot;MOB v1 vs. MOB v2&quot;">​</a></h2><table><thead><tr><th></th><th>MOB v1</th><th>MOB v2</th></tr></thead><tbody><tr><td><strong>Machines</strong></td><td>Mobi One V1, Frame Station V1</td><td>Mobi One V2, Frame Station V2, Robobrick, Isolation machine</td></tr><tr><td><strong>Configuration file</strong></td><td>Text file (<code>key=value</code>)</td><td>XML</td></tr><tr><td><strong>Plate nailers</strong></td><td>4, 5, 6, one head at a time</td><td>24, 25, 26 and 44, 45, 46, alone or in twin pairs</td></tr><tr><td><strong>Flooring</strong></td><td>Not supported</td><td>When the configuration file declares flooring stations</td></tr><tr><td><strong>Bricks, insulation</strong></td><td>Not supported</td><td>Robobrick and Isolation machine</td></tr><tr><td><strong>Glue</strong></td><td>Frame glue only</td><td>Glue lines in the plate layers, one head or two</td></tr></tbody></table>`,23),l=[i];function r(d,p,c,h,m,f){return a(),n("div",null,l)}const v=t(o,[["render",r]]);export{b as __pageData,v as default};
